import { Activity, ArrowRight, type LucideIcon } from '@gntik-ai/icons';
import { Button, Card, cn, Link, Sparkline, Toggle, ToggleGroup, type SparklineTone } from '@gntik-ai/ui';
import { useState } from 'react';
import { TrendDelta, type KpiDelta } from '../shared/TrendDelta';
import { STAT_RANGES } from './fixtures';

export interface StatCardRange {
  /** Range key, e.g. "7d". */
  value: string;
  /** Toggle label. */
  label: string;
  /** Pre-formatted headline value for this range. */
  stat: string;
  delta?: KpiDelta;
  /** Series drawn under the value, oldest first. */
  series: readonly number[];
}

export interface StatCardProps {
  label?: string;
  /** Leading icon tile (a lucide icon). */
  icon?: LucideIcon;
  /** One entry per range; with a single entry the range toggle is hidden. */
  ranges?: readonly StatCardRange[];
  /** Initially selected range (uncontrolled). */
  defaultRange?: string;
  /** Selected range (controlled). */
  range?: string;
  onRangeChange?: (range: string) => void;
  /** `area` line (default) or daily `bar` shape. */
  chart?: 'area' | 'bar';
  tone?: SparklineTone;
  /** Footer link-style action ("View requests →"). */
  action?: { label: string; onClick?: () => void; href?: string };
  /** Heading level of the title, to fit the page outline (default h3). */
  titleAs?: 'h2' | 'h3' | 'h4';
  className?: string;
}

/** A single rich stat: icon tile, label, value, delta, a range toggle and a trend chart, with a footer action. */
export function StatCard({
  label = 'Requests',
  icon: IconCmp = Activity,
  ranges = STAT_RANGES,
  defaultRange,
  range: rangeProp,
  onRangeChange,
  chart = 'area',
  tone = 'primary',
  action = { label: 'View requests' },
  titleAs: TitleTag = 'h3',
  className,
}: StatCardProps) {
  const [inner, setInner] = useState(defaultRange ?? ranges[0]?.value ?? '');
  const current = rangeProp ?? inner;
  const active = ranges.find((r) => r.value === current) ?? ranges[0];
  const select = (next: string) => {
    setInner(next);
    onRangeChange?.(next);
  };
  return (
    <Card className={cn('flex flex-col', className)}>
      <div className="flex flex-1 flex-col p-5">
        <div className="flex items-start justify-between gap-3">
          <div className="flex min-w-0 items-center gap-3">
            <span className="inline-flex size-9 shrink-0 items-center justify-center rounded-md bg-primary/14 text-primary-chip-text">
              <IconCmp size={18} aria-hidden />
            </span>
            <TitleTag className="truncate text-[13px] font-medium text-muted-foreground">{label}</TitleTag>
          </div>
          {ranges.length > 1 && (
            <ToggleGroup
              aria-label={`${label} range`}
              size="sm"
              value={[current]}
              onValueChange={(v) => {
                const next = v[0];
                if (next) select(next);
              }}
            >
              {ranges.map((r) => (
                <Toggle key={r.value} value={r.value} className="font-mono">
                  {r.label}
                </Toggle>
              ))}
            </ToggleGroup>
          )}
        </div>
        {active && (
          <>
            <p className="mt-3 flex flex-wrap items-baseline gap-x-2 gap-y-1" aria-live="polite">
              <span className="text-[26px] font-semibold tracking-tight text-foreground tabular-nums">{active.stat}</span>
              {active.delta && <TrendDelta {...active.delta} />}
            </p>
            {active.delta?.note && <p className="mt-1 text-[12px] text-muted-foreground">{active.delta.note}</p>}
            <Sparkline
              data={active.series}
              label={`${label}, ${active.label}`}
              variant={chart === 'bar' ? 'bar' : 'line'}
              area={chart === 'area'}
              markers={chart === 'area' ? ['last'] : []}
              tone={tone}
              width={280}
              height={56}
              className="mt-4 block h-auto w-full"
            />
          </>
        )}
      </div>
      {action && (
        <div className="border-t border-border px-5 py-3">
          {action.href ? (
            <Link underline="hover" href={action.href} className="inline-flex items-center gap-1 text-[12.5px] font-semibold">
              {action.label}
              <ArrowRight size={14} aria-hidden />
            </Link>
          ) : (
            <Button variant="ghost" size="sm" trailingIcon={ArrowRight} className="-mx-2 text-primary-text hover:text-primary-text" onClick={action.onClick}>
              {action.label}
            </Button>
          )}
        </div>
      )}
    </Card>
  );
}

import type { StatCardRange } from './StatCard';

/** Requests per range: the value and delta recalculate when the range changes. */
export const STAT_RANGES: StatCardRange[] = [
  {
    value: '7d',
    label: '7d',
    stat: '38,921',
    delta: { value: '+12.4%', direction: 'up', sentiment: 'positive', note: 'vs. previous 7 days' },
    series: [31, 34, 33, 38, 36, 41, 39],
  },
  {
    value: '30d',
    label: '30d',
    stat: '1.09M',
    delta: { value: '+9.6%', direction: 'up', sentiment: 'positive', note: 'vs. previous 30 days' },
    series: [28, 30, 29, 33, 31, 30, 34, 32, 36, 35, 38, 37],
  },
  {
    value: '90d',
    label: '90d',
    stat: '3.02M',
    delta: { value: '+22.8%', direction: 'up', sentiment: 'positive', note: 'vs. previous 90 days' },
    series: [22, 24, 23, 26, 25, 28, 27, 30, 29, 33, 32, 36],
  },
];

import { cn } from '@gntik-ai/ui';

/** Arrow shape of a change. */
export type DeltaDirection = 'up' | 'down' | 'flat';
/** Whether the change is good, bad or neither — independent of its direction (lower latency is good). */
export type DeltaSentiment = 'positive' | 'negative' | 'neutral';

export interface KpiDelta {
  /** Display text, e.g. "+12.4%". */
  value: string;
  direction: DeltaDirection;
  sentiment: DeltaSentiment;
  /** Comparison context, e.g. "vs. previous 24h". */
  note?: string;
}

const SENTIMENT_CLASS: Record<DeltaSentiment, string> = {
  positive: 'text-success-text',
  negative: 'text-destructive-text',
  neutral: 'text-muted-foreground',
};

const DIRECTION_TEXT: Record<DeltaDirection, string> = { up: 'Increased by', down: 'Decreased by', flat: 'Unchanged:' };
const SENTIMENT_TEXT: Record<DeltaSentiment, string> = { positive: 'favourable', negative: 'unfavourable', neutral: '' };

export interface TrendDeltaProps extends KpiDelta {
  className?: string;
}

/**
 * Mono delta with a triangle: the arrow follows `direction`, the colour follows `sentiment`.
 * Screen readers get the direction and sentiment in words.
 */
export function TrendDelta({ value, direction, sentiment, className }: TrendDeltaProps) {
  const sr = [DIRECTION_TEXT[direction], value, SENTIMENT_TEXT[sentiment] && `(${SENTIMENT_TEXT[sentiment]})`].filter(Boolean).join(' ');
  return (
    <span
      data-sentiment={sentiment}
      className={cn('inline-flex items-center gap-1 font-mono text-[12px] font-medium tabular-nums', SENTIMENT_CLASS[sentiment], className)}
    >
      <svg width="9" height="9" viewBox="0 0 10 10" aria-hidden className="shrink-0">
        {direction === 'up' && <path d="M5 1.5 9 8.5H1z" fill="currentColor" />}
        {direction === 'down' && <path d="M5 8.5 1 1.5h8z" fill="currentColor" />}
        {direction === 'flat' && <path d="M1 4h8v2H1z" fill="currentColor" />}
      </svg>
      <span aria-hidden>{value}</span>
      <span className="sr-only">{sr}</span>
    </span>
  );
}
